  "supportive_card_ids": ["C25", "C32", "C40", "C54", "C62", "C74", "C82", "C85", "C86"],
  "contradictory_card_ids": ["C01", "C03", "C09", "C13", "C14", "C15", "C19", "C12", "C22"],
  "prediction_basis_card_ids": ["C25", "C32", "C40", "C54", "C62", "C74", "C82", "C85", "C86"],
  "claims": [
    {
      "claim": "Zeaxanthin, a highly lipophilic polyene with two hydroxyl groups, shows extremely low oral bioavailability in rats (plasma and urine below quantitation limits at 20-100 mg/kg), attributed to poor gut luminal solubility/stability, limited gut absorption, and hepatic first-pass metabolism; this is the most structurally relevant low-F context for the query's long polyene and high logP.",
      "card_ids": ["C25", "C32", "C62", "C82", "C86"]
    },
    {
      "claim": "Apatinib, an oral anilide with molecular weight similar to the query, has reported human oral bioavailability of 10-20% and dog bioavailability of 9-15%, providing affirmative threshold-relevant evidence that an anilide scaffold with high lipophilicity can fall below F=20%.",
      "card_ids": ["C40", "C54", "C74", "C85"]
    },
    {
      "claim": "High-F anilide contexts (leflunomide, teriflunomide) are less transferable to the query because they are much smaller, less lipophilic, and in the case of teriflunomide ionized at physiological pH, whereas the query is neutral with logP 6.86 and a long conjugated polyene.",
      "card_ids": ["C09", "C13", "C19", "C03", "C10"]
    },
    {
      "claim": "High-F phenolic contexts (desvenlafaxine, estetrol) are also limited in transfer because they are small, polar molecules with much lower logP than the query.",
      "card_ids": ["C01", "C14", "C15"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "changed",
      "card_ids": ["C25", "C32", "C62", "C82", "C86", "C40", "C54", "C74", "C85"]
    },
    {
      "family": "associated_nonvoting_records",
      "applicability": "low",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": ["C29", "C45", "C50", "C63", "C84", "C89", "C26", "C42", "C30", "C72"]
    }
  ],
  "evidence_gaps": [
    "No direct fenretinide-specific absolute oral bioavailability measurement is present in the supplied records.",
    "Zeaxanthin low-F data are from rats and may not fully transfer to humans; human dietary data show bioavailability in lipid-rich matrices.",
    "Apatinib human F range 10-20% is borderline and partly based on unpublished dog data; species and formulation differences limit transfer.",
    "High-F anilide contexts (leflunomide/teriflunomide) differ substantially in lipophilicity, size, and ionization, limiting transfer to the query.",
    "No measured solubility/dissolution or first-pass metabolism data for the query; the logP-based solubility concern is a physicochemical prior, not endpoint evidence.",
    "The leflunomide isomer low-F record (C44) is ambiguous and was not used as a primary basis for the decision."
  ],
  "decision_summary": "Level 2 adds affirmative low-F context from zeaxanthin (extremely low in rats) and apatinib (10-20% human, 9-15% dog), which are more structurally relevant to the query's lipophilic polyene and anilide scaffold than the smaller, more polar high-F anilides. Combined with the unfavorable solubility prior and absence of direct fenretinide F data, the balance supports F < 20%, so the prediction is flipped to low with low confidence."
}

